#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int rounds;
    cin >> rounds;
    vector<int> alice_moves(rounds);
    for (int i = 0; i < rounds; ++i) {
        cin >> alice_moves[i];
    }
    vector<int> bob_moves(rounds);
    for (int i = 0; i < rounds; ++i) {
        cin >> bob_moves[i];
    }
    // Rotate bob_moves by one position
    int first_bob_move = bob_moves[0];
    for (int i = 0; i < rounds - 1; ++i) {
        bob_moves[i] = bob_moves[i + 1];
    }
    bob_moves[rounds - 1] = first_bob_move;

    int min_win = 0, max_win = 0;
    for (int i = 0; i < rounds; ++i) {
        min_win += min(alice_moves[i], bob_moves[i]);
    }

    int max_bob = *max_element(bob_moves.begin(), bob_moves.end());
    for (int i = 0; i < rounds; ++i) {
        if (bob_moves[i] == max_bob && bob_moves[i] + alice_moves[i] > min_win) {
            min_win = bob_moves[i] + alice_moves[i];
        }
    }

    int max_alice = *max_element(alice_moves.begin(), alice_moves.end());
    for (int i = 0; i < rounds; ++i) {
        if (alice_moves[i] == max_alice && alice_moves[i] + bob_moves[i] > min_win) {
            min_win = alice_moves[i] + bob_moves[i];
        }
    }

    if (min_win > rounds) {
        min_win -= rounds;
    } else {
        min_win = 0;
    }

    cout << min_win << " " << max_win << "\n";

    return 0;
}
